"""Synthetic race dataset generated by the reference simulator.

Each session has hidden variation (track temperature, tyre degradation scale)
and each driver runs a randomly drawn legal strategy, which gives the models
wide coverage of tyre ages, compounds and drive modes.
"""
from __future__ import annotations

import numpy as np
import pandas as pd

from race_engineer.config import CIRCUITS, COMPOUND_NAMES, COMPOUNDS, DRIVERS, MODE_NAMES, MODES
from race_engineer.data.telemetry_synth import lap_seed, synth_lap_telemetry
from race_engineer.features.telemetry import TELEMETRY_COLUMNS, aggregate_arrays
from race_engineer.sim.physics import PhysicsPaceModel
from race_engineer.sim.race import Plan, RaceState, Stint, build_frame, check_plan

LAP_NOISE_S = 0.25
MODE_WEIGHTS = [0.2, 0.6, 0.2]   # push, normal, conserve


def random_plan(state: RaceState, rng: np.random.Generator) -> Plan:
    total = state.laps_remaining
    for _ in range(1000):
        n_stops = rng.choice([1, 2, 3], p=[0.45, 0.45, 0.10])
        cuts = np.sort(rng.choice(np.arange(4, total - 3), n_stops, replace=False))
        lens = np.diff(np.concatenate([[0], cuts, [total]]))
        comps = [state.compound] + list(rng.choice(COMPOUND_NAMES, n_stops))
        modes = rng.choice(MODE_NAMES, n_stops + 1, p=MODE_WEIGHTS)
        plan = Plan(tuple(Stint(c, int(n), str(m)) for c, n, m in zip(comps, lens, modes)))
        if not check_plan(plan, state):
            return plan
    raise RuntimeError("could not draw a legal plan")


def generate_dataset(seasons=(2021, 2022, 2023, 2024, 2025), seed: int = 7,
                     with_telemetry: bool = True) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    frames = []
    for season in seasons:
        for circuit in CIRCUITS.values():
            session_id = f"{season}-{circuit.name}"
            temp = float(rng.uniform(26, 46))
            pace = PhysicsPaceModel(deg_scale=float(rng.lognormal(0.0, 0.08)))
            for driver in DRIVERS:
                start = str(rng.choice(COMPOUND_NAMES, p=[0.35, 0.45, 0.20]))
                state = RaceState(circuit.name, driver, compound=start, track_temp=temp)
                plan = random_plan(state, rng)
                f = build_frame([plan], state, pace.fuel_table(circuit.name))
                n = len(f)
                lap = pace.predict(f) + rng.normal(0, LAP_NOISE_S, n)
                lap += np.where(rng.random(n) < 0.02, rng.uniform(1.0, 3.0, n), 0.0)   # traffic
                lap[0] += 4.0                                                           # standing start
                pit_in = f["pit_in"].to_numpy()
                pit_out = np.concatenate([[False], pit_in[:-1]])
                loss = circuit.pit_loss_s + rng.normal(0, 0.6, n)
                lap += 0.4 * loss * pit_in + 0.6 * loss * pit_out
                f = f.assign(session_id=session_id, season=season, lap_time_s=lap,
                             is_pit_in_lap=pit_in, is_pit_out_lap=pit_out)
                frames.append(f.drop(columns=["plan_id", "pit_in", "wear"]))
    laps = pd.concat(frames, ignore_index=True)

    split = rng.dirichlet([3000, 3600, 3400], len(laps))
    for i in range(3):
        laps[f"sector{i + 1}_s"] = laps["lap_time_s"] * split[:, i]
    laps["fuel_is_estimated"] = False

    # Fuel burned and telemetry share a per-lap "lift" amount, so driving behaviour
    # seen in telemetry genuinely explains fuel use beyond the nominal drive mode.
    base_q = laps["drive_mode"].map({m: MODES[m].lift_quantile for m in MODES}).to_numpy()
    lift_q = np.clip(base_q + rng.normal(0, 0.02, len(laps)), 0.5, 1.0)
    nominal = laps["circuit"].map({c.name: c.fuel_per_lap_kg for c in CIRCUITS.values()}).to_numpy()
    nominal = nominal * laps["drive_mode"].map({m: MODES[m].fuel_mult for m in MODES}).to_numpy()
    laps["fuel_used_kg"] = nominal * (1 + 0.5 * (lift_q - base_q)) * (1 + rng.normal(0, 0.01, len(laps)))

    if with_telemetry:
        rows = []
        for r, q in zip(laps.itertuples(index=False), lift_q):
            tel = synth_lap_telemetry(r.circuit, r.lap_time_s, r.drive_mode,
                                      lap_seed(r.session_id, r.driver, r.lap_number), q)
            rows.append(aggregate_arrays(*(tel[c].to_numpy() for c in TELEMETRY_COLUMNS)))
        laps = pd.concat([laps, pd.DataFrame(rows)], axis=1)

    # Realistic defects for the validation stage to handle.
    laps.loc[rng.random(len(laps)) < 0.003, "lap_time_s"] = np.nan
    return laps
